// Retorna os dados no formato esperado pelo agente
const data = $json.data || [];

if (data.length === 0) {
  return {
    encontrado: false,
    mensagem: 'Nenhum cliente encontrado'
  };
}

if (data.length === 1) {
  return {
    encontrado: true,
    ambiguo: false,
    cliente_id: data[0].id,
    nome: data[0].nome,
    telefone: data[0].telefone,
    endereco: data[0].endereco
  };
}

// Se houver múltiplos resultados
return {
  encontrado: true,
  ambiguo: true,
  clientes: data.map(c => ({
    id: c.id,
    nome: c.nome,
    telefone: c.telefone
  }))
};
